import { courseChallenges } from '../course.js';

// Original Thai translations. Correctness/order comes from the unchanged source curriculum.
const sourceById = Object.fromEntries(courseChallenges.map(question => [question.id, question]));
export const courseThai = {};
function lesson(id, rows) {
  rows.forEach(([principle,prompt,explanation,takeaway,good,bad],index) => {
    const key=`course-${id}-${index+1}`;
    const source=sourceById[key];
    if(!source)throw new Error(`Unknown course translation: ${key}`);
    const option=([heading,detail])=>({label:heading,heading,detail});
    courseThai[key]={title:principle,prompt,principle,explanation,takeaway,options:(source.correct===0?[good,bad]:[bad,good]).map(option)};
  });
}

